def choose_operation(name):
    if name == 'double':
        return lambda x: x * 2
    elif name == 'square':
        return lambda x: x * x
    elif name == 'negate':
        return lambda x: -x
    return lambda x: x

def choose_greeting(language):
    if language == 'en':
        return lambda name: 'Hello, ' + name
    elif language == 'nl':
        return lambda name: 'Hallo, ' + name
    elif language == 'tr':
        return lambda name: 'Merhaba, ' + name
    return lambda name: 'Hi, ' + name

